/// <reference types="astro/client" />

// `Env` (DB, BUCKET, ASSETS, EVENT_SECRET, RATE_LIMIT_SECRET) is the global
// interface generated by `wrangler types` into worker-configuration.d.ts.
// Runtime bindings are accessed via `getEnv()` (src/lib/runtime.ts), not
// `locals.runtime.env` (removed in Astro v6/adapter v14).
declare namespace App {
	interface Locals {
		/** Resolved auth context for this request, or null if unauthenticated. */
		auth: import('./lib/auth/types').AuthContext | null;
	}
}
